//! A native Wayland client: the wire format, object ids and fd passing.
//!
//! Typed bindings generated by tools/wayland-zig.py call `Proxy.send` for
//! requests and receive decoded `Event` unions through `Proxy.listen`.
//! Like libwayland, file descriptors passed in requests are duplicated, so
//! callers keep ownership of theirs; descriptors received in events belong
//! to the handler.
const std = @import("std");

pub const Fd = i32;

pub const Message = struct {
    name: [:0]const u8,
    /// libwayland's argument codes without the version prefix: i u f s o n a h, `?` marks nullable.
    signature: [:0]const u8,
    since: u32 = 1,
    destructor: bool = false,
    /// The interface of a typed new_id argument, resolved lazily to allow cycles.
    new_id: ?*const fn () *const Interface = null,
};

pub const Interface = struct {
    name: [:0]const u8,
    version: u32,
    requests: []const Message,
    events: []const Message,
};

/// Placeholder for the new_id argument of a request.
pub const NewId = struct {};
pub const new_id: NewId = .{};

const Handler = *const fn (data: ?*anyopaque, incoming: *Incoming) void;

const Object = struct {
    interface: *const Interface,
    version: u32,
    data: ?*anyopaque = null,
    handler: ?Handler = null,
    /// False once destroyed locally; the id stays reserved until delete_id.
    live: bool = true,
};

const server_base: u32 = 0xff000000;
const max_message = 4096;
/// libwayland's per-sendmsg descriptor limit.
const max_fds = 28;

pub const Error = error{ ConnectionFailed, ConnectionClosed, Protocol, OutOfMemory, IoFailed };

pub const Proxy = struct {
    connection: *Connection,
    id: u32,

    pub fn version(self: Proxy) u32 {
        const object = self.connection.object(self.id) orelse return 0;
        return object.version;
    }

    /// Routes this object's events, decoded as `T.Event`, to `handler`.
    pub fn listen(self: Proxy, comptime T: type, comptime Data: type, data: *Data, comptime handler: fn (*Data, T, T.Event) void) void {
        const object = self.connection.object(self.id) orelse return;
        object.data = data;
        object.handler = &Dispatcher(T, Data, handler).dispatch;
    }

    /// Releases the object locally without telling the server.
    pub fn forget(self: Proxy) void {
        self.connection.retire(self.id);
    }

    pub fn send(self: Proxy, comptime opcode: u16, comptime message: Message, new_interface: ?*const Interface, bind_version: ?u32, args: anytype) Proxy {
        return self.connection.marshal(self, opcode, message, new_interface, bind_version, args) catch |err| {
            self.connection.fail(err);
            return .{ .connection = self.connection, .id = 0 };
        };
    }
};

/// One received message while its handler runs; strings and arrays point into it.
pub const Incoming = struct {
    connection: *Connection,
    id: u32,
    opcode: u16,
    body: []const u8,
    fds: []const Fd,
    taken: usize = 0,

    fn word(self: *Incoming, at: *usize) Error!u32 {
        if (at.* + 4 > self.body.len) return error.Protocol;
        defer at.* += 4;
        return std.mem.readInt(u32, self.body[at.*..][0..4], .little);
    }

    fn bytes(self: *Incoming, at: *usize) Error![]const u8 {
        const len = try self.word(at);
        const padded = std.mem.alignForward(usize, len, 4);
        if (at.* + padded > self.body.len) return error.Protocol;
        defer at.* += padded;
        return self.body[at.*..][0..len];
    }

    fn object(self: *Incoming, comptime T: type, id: u32) T {
        if (T == Proxy) return .{ .connection = self.connection, .id = id };
        switch (@typeInfo(T)) {
            .optional => |o| return if (id == 0) null else self.object(o.child, id),
            else => return .{ .proxy = .{ .connection = self.connection, .id = id } },
        }
    }

    /// Decodes an event payload struct according to the event's signature.
    fn decode(self: *Incoming, comptime S: type, comptime signature: []const u8) Error!S {
        var result: S = undefined;
        const info = @typeInfo(S).@"struct";
        var at: usize = 0;
        comptime var field = 0;
        comptime var nullable = false;
        inline for (signature) |code| {
            if (code == '?') {
                nullable = true;
                continue;
            }
            const name = info.field_names[field];
            const T = info.field_types[field];
            switch (code) {
                'i' => @field(result, name) = @bitCast(try self.word(&at)),
                'u' => @field(result, name) = try self.word(&at),
                'f' => @field(result, name) = @as(f64, @floatFromInt(@as(i32, @bitCast(try self.word(&at))))) / 256,
                's' => {
                    const value = try self.bytes(&at);
                    if (value.len == 0) {
                        if (!nullable) return error.Protocol;
                        @field(result, name) = if (@typeInfo(T) == .optional) null else "";
                    } else {
                        if (value[value.len - 1] != 0) return error.Protocol;
                        @field(result, name) = value[0 .. value.len - 1 :0];
                    }
                },
                'a' => @field(result, name) = try self.bytes(&at),
                'o', 'n' => {
                    const id = try self.word(&at);
                    if (id == 0 and !nullable) return error.Protocol;
                    @field(result, name) = self.object(T, id);
                },
                'h' => {
                    if (self.taken >= self.fds.len) return error.Protocol;
                    @field(result, name) = self.fds[self.taken];
                    self.taken += 1;
                },
                else => @compileError("unknown signature code"),
            }
            field += 1;
            nullable = false;
        }
        comptime std.debug.assert(field == info.field_names.len);
        return result;
    }
};

fn Dispatcher(comptime T: type, comptime Data: type, comptime handler: fn (*Data, T, T.Event) void) type {
    return struct {
        fn dispatch(data: ?*anyopaque, incoming: *Incoming) void {
            const info = @typeInfo(T.Event).@"union";
            inline for (info.field_names, info.field_types, 0..) |name, Payload, opcode| {
                if (incoming.opcode == opcode) {
                    const payload = incoming.decode(Payload, T.interface.events[opcode].signature) catch |err| {
                        incoming.connection.fail(err);
                        return;
                    };
                    const self: T = .{ .proxy = .{ .connection = incoming.connection, .id = incoming.id } };
                    handler(@ptrCast(@alignCast(data)), self, @unionInit(T.Event, name, payload));
                    return;
                }
            }
        }
    };
}

// wl_display and wl_callback, which the connection itself needs for errors,
// id recycling and round trips. Generated bindings carry the full protocol.
const display_interface: Interface = .{ .name = "wl_display", .version = 1, .requests = &.{
    .{ .name = "sync", .signature = "n", .new_id = struct {
        fn get() *const Interface {
            return &callback_interface;
        }
    }.get },
    .{ .name = "get_registry", .signature = "n" },
}, .events = &.{
    .{ .name = "error", .signature = "ous" },
    .{ .name = "delete_id", .signature = "u" },
} };
const callback_interface: Interface = .{ .name = "wl_callback", .version = 1, .requests = &.{}, .events = &.{
    .{ .name = "done", .signature = "u", .destructor = true },
} };

pub const Connection = struct {
    allocator: std.mem.Allocator,
    fd: Fd,
    client: std.ArrayList(?Object) = .empty,
    server: std.ArrayList(?Object) = .empty,
    free: std.ArrayList(u32) = .empty,
    out: [4 * max_message]u8 = undefined,
    out_len: usize = 0,
    out_fds: [max_fds]Fd = undefined,
    out_fd_count: usize = 0,
    in: [4 * max_message]u8 = undefined,
    in_len: usize = 0,
    in_fds: std.ArrayList(Fd) = .empty,
    failure: ?Error = null,
    /// WAYLAND_DEBUG=1 or WAYLAND_DEBUG=client logs messages like libwayland.
    debug: bool = false,

    /// Connects like libwayland: WAYLAND_SOCKET, then WAYLAND_DISPLAY in XDG_RUNTIME_DIR.
    pub fn connect(allocator: std.mem.Allocator) Error!*Connection {
        if (std.c.getenv("WAYLAND_SOCKET")) |value| {
            const fd = std.fmt.parseInt(Fd, std.mem.span(value), 10) catch return error.ConnectionFailed;
            _ = unsetenv("WAYLAND_SOCKET");
            if (std.c.fcntl(fd, std.c.F.SETFD, @as(c_int, std.c.FD_CLOEXEC)) < 0) return error.ConnectionFailed;
            return fromFd(allocator, fd);
        }
        const socket_name: []const u8 = if (std.c.getenv("WAYLAND_DISPLAY")) |value| std.mem.span(value) else "wayland-0";
        var address: SockaddrUn = .{};
        if (socket_name.len > 0 and socket_name[0] == '/') {
            if (socket_name.len >= address.path.len) return error.ConnectionFailed;
            @memcpy(address.path[0..socket_name.len], socket_name);
        } else {
            const runtime = std.mem.span(std.c.getenv("XDG_RUNTIME_DIR") orelse return error.ConnectionFailed);
            _ = std.fmt.bufPrint(&address.path, "{s}/{s}", .{ runtime, socket_name }) catch return error.ConnectionFailed;
        }
        const fd = std.c.socket(1, 1 | 0o2000000, 0); // AF_UNIX, SOCK_STREAM | SOCK_CLOEXEC
        if (fd < 0) return error.ConnectionFailed;
        errdefer _ = std.c.close(fd);
        if (std.c.connect(fd, @ptrCast(&address), @sizeOf(SockaddrUn)) != 0) return error.ConnectionFailed;
        return fromFd(allocator, fd);
    }

    /// Takes ownership of a connected socket.
    pub fn fromFd(allocator: std.mem.Allocator, fd: Fd) Error!*Connection {
        const self = try allocator.create(Connection);
        errdefer allocator.destroy(self);
        const debug = if (std.c.getenv("WAYLAND_DEBUG")) |value| blk: {
            const text = std.mem.span(value);
            break :blk std.mem.eql(u8, text, "1") or std.mem.indexOf(u8, text, "client") != null;
        } else false;
        self.* = .{ .allocator = allocator, .fd = fd, .debug = debug };
        // Id 0 is null; id 1 is the display.
        try self.client.appendSlice(allocator, &.{ null, .{ .interface = &display_interface, .version = 1, .data = self, .handler = &displayEvent } });
        return self;
    }

    pub fn deinit(self: *Connection) void {
        for (self.in_fds.items) |fd| _ = std.c.close(fd);
        for (self.out_fds[0..self.out_fd_count]) |fd| _ = std.c.close(fd);
        self.in_fds.deinit(self.allocator);
        self.client.deinit(self.allocator);
        self.server.deinit(self.allocator);
        self.free.deinit(self.allocator);
        _ = std.c.close(self.fd);
        self.allocator.destroy(self);
    }

    /// The wl_display object; wrap it in the generated `wl_display` type.
    pub fn display(self: *Connection) Proxy {
        return .{ .connection = self, .id = 1 };
    }

    pub fn getFd(self: *const Connection) Fd {
        return self.fd;
    }

    fn fail(self: *Connection, err: Error) void {
        if (self.failure == null) self.failure = err;
    }

    fn object(self: *Connection, id: u32) ?*Object {
        if (id >= server_base) {
            const index = id - server_base;
            if (index >= self.server.items.len) return null;
            return if (self.server.items[index]) |*value| value else null;
        }
        if (id >= self.client.items.len) return null;
        return if (self.client.items[id]) |*value| value else null;
    }

    fn allocate(self: *Connection, value: Object) Error!u32 {
        if (self.free.pop()) |id| {
            self.client.items[id] = value;
            return id;
        }
        try self.client.append(self.allocator, value);
        return @intCast(self.client.items.len - 1);
    }

    fn retire(self: *Connection, id: u32) void {
        const value = self.object(id) orelse return;
        value.live = false;
        value.handler = null;
        value.data = null;
    }

    fn marshal(self: *Connection, proxy: Proxy, comptime opcode: u16, comptime message: Message, new_interface: ?*const Interface, bind_version: ?u32, args: anytype) Error!Proxy {
        if (self.failure) |err| return err;
        const target = self.object(proxy.id) orelse return error.Protocol;
        if (!target.live) return error.Protocol;
        if (message.since > target.version) return error.Protocol;
        var buffer: [max_message]u8 = undefined;
        var len: usize = 8;
        var fds: [max_fds]Fd = undefined;
        var fd_count: usize = 0;
        errdefer for (fds[0..fd_count]) |fd| {
            _ = std.c.close(fd);
        };
        var created: u32 = 0;
        const fields = @typeInfo(@TypeOf(args)).@"struct".field_names;
        comptime var field = 0;
        inline for (message.signature) |code| {
            if (code == '?') continue;
            const value = @field(args, fields[field]);
            field += 1;
            switch (code) {
                'i' => try put(&buffer, &len, @bitCast(@as(i32, value))),
                'u' => try put(&buffer, &len, @as(u32, value)),
                'f' => try put(&buffer, &len, @bitCast(@as(i32, @intFromFloat(@round(@as(f64, value) * 256))))),
                's' => try putString(&buffer, &len, value),
                'a' => try putArray(&buffer, &len, value),
                'o' => try put(&buffer, &len, objectId(value)),
                'n' => {
                    if (@TypeOf(value) != NewId) @compileError("new_id arguments take wire.new_id");
                    const interface = new_interface orelse (message.new_id orelse return error.Protocol)();
                    created = try self.allocate(.{ .interface = interface, .version = bind_version orelse target.version });
                    try put(&buffer, &len, created);
                },
                'h' => {
                    if (fd_count == max_fds) return error.Protocol;
                    const copy = std.c.fcntl(value, std.c.F.DUPFD_CLOEXEC, @as(c_int, 0));
                    if (copy < 0) return error.IoFailed;
                    fds[fd_count] = copy;
                    fd_count += 1;
                },
                else => @compileError("unknown signature code"),
            }
        }
        comptime std.debug.assert(field == fields.len);
        std.mem.writeInt(u32, buffer[0..4], proxy.id, .little);
        std.mem.writeInt(u32, buffer[4..8], @as(u32, @intCast(len)) << 16 | opcode, .little);
        if (self.debug) self.trace(" -> ", target.interface.name, proxy.id, message, buffer[8..len]);
        if (self.out_len + len > self.out.len or self.out_fd_count + fd_count > max_fds) try self.flush();
        @memcpy(self.out[self.out_len..][0..len], buffer[0..len]);
        self.out_len += len;
        @memcpy(self.out_fds[self.out_fd_count..][0..fd_count], fds[0..fd_count]);
        self.out_fd_count += fd_count;
        if (message.destructor) self.retire(proxy.id);
        return .{ .connection = self, .id = created };
    }

    /// Sends buffered requests, blocking until the socket accepts them.
    pub fn flush(self: *Connection) Error!void {
        if (self.failure) |err| return err;
        while (self.out_len > 0) {
            var iov = [_]std.posix.iovec_const{.{ .base = &self.out, .len = self.out_len }};
            var control: [cmsgSpace(max_fds)]u8 align(8) = @splat(0);
            var header: std.c.msghdr_const = .{ .name = null, .namelen = 0, .iov = &iov, .iovlen = 1, .control = null, .controllen = 0, .flags = 0 };
            if (self.out_fd_count > 0) {
                const fds = self.out_fds[0..self.out_fd_count];
                writeCmsg(&control, fds);
                header.control = &control;
                header.controllen = cmsgSpace(fds.len);
            }
            const sent = std.c.sendmsg(self.fd, &header, 0x4000); // MSG_NOSIGNAL
            if (sent < 0) {
                if (std.c._errno().* == 4) continue; // EINTR
                return self.broken(error.IoFailed);
            }
            for (self.out_fds[0..self.out_fd_count]) |fd| _ = std.c.close(fd);
            self.out_fd_count = 0;
            const count: usize = @intCast(sent);
            std.mem.copyForwards(u8, self.out[0 .. self.out_len - count], self.out[count..self.out_len]);
            self.out_len -= count;
        }
    }

    fn broken(self: *Connection, err: Error) Error {
        self.fail(err);
        return err;
    }

    /// Reads whatever the socket holds without blocking; returns whether data arrived.
    pub fn read(self: *Connection) Error!bool {
        if (self.failure) |err| return err;
        if (self.in_len == self.in.len) return self.broken(error.Protocol);
        var iov = [_]std.posix.iovec{.{ .base = self.in[self.in_len..].ptr, .len = self.in.len - self.in_len }};
        var control: [cmsgSpace(max_fds)]u8 align(8) = undefined;
        var header: std.c.msghdr = .{ .name = null, .namelen = 0, .iov = &iov, .iovlen = 1, .control = &control, .controllen = control.len, .flags = 0 };
        const received = while (true) {
            const result = std.c.recvmsg(self.fd, &header, 0x40 | 0x40000000); // MSG_DONTWAIT | MSG_CMSG_CLOEXEC
            if (result >= 0) break result;
            switch (std.c._errno().*) {
                4 => continue,
                11 => return false, // EAGAIN
                else => return self.broken(error.IoFailed),
            }
        };
        try self.takeFds(control[0..header.controllen]);
        if (header.flags & 0x8 != 0) return self.broken(error.Protocol); // MSG_CTRUNC lost descriptors
        if (received == 0) return self.broken(error.ConnectionClosed);
        self.in_len += @intCast(received);
        return true;
    }

    fn takeFds(self: *Connection, control: []const u8) Error!void {
        var offset: usize = 0;
        while (offset + 16 <= control.len) {
            const len = std.mem.readInt(usize, control[offset..][0..8], .little);
            const level = std.mem.readInt(i32, control[offset + 8 ..][0..4], .little);
            const kind = std.mem.readInt(i32, control[offset + 12 ..][0..4], .little);
            if (len < 16 or offset + len > control.len) break;
            if (level == 1 and kind == 1) { // SOL_SOCKET, SCM_RIGHTS
                var at = offset + 16;
                while (at + 4 <= offset + len) : (at += 4) {
                    const fd = std.mem.readInt(i32, control[at..][0..4], .little);
                    self.in_fds.append(self.allocator, fd) catch {
                        _ = std.c.close(fd);
                        return self.broken(error.OutOfMemory);
                    };
                }
            }
            offset += std.mem.alignForward(usize, len, 8);
        }
    }

    /// Dispatches every complete message already read.
    pub fn dispatchPending(self: *Connection) Error!void {
        while (self.failure == null and self.in_len >= 8) {
            const id = std.mem.readInt(u32, self.in[0..4], .little);
            const word = std.mem.readInt(u32, self.in[4..8], .little);
            const size: usize = word >> 16;
            if (size < 8 or size > max_message or size % 4 != 0) return self.broken(error.Protocol);
            if (self.in_len < size) break;
            // Copy out first so handlers may send, read or round-trip.
            var message: [max_message]u8 = undefined;
            @memcpy(message[0..size], self.in[0..size]);
            std.mem.copyForwards(u8, self.in[0 .. self.in_len - size], self.in[size..self.in_len]);
            self.in_len -= size;
            try self.deliver(id, @intCast(word & 0xffff), message[8..size]);
        }
        if (self.failure) |err| return err;
    }

    fn deliver(self: *Connection, id: u32, opcode: u16, body: []const u8) Error!void {
        const target = self.object(id) orelse return self.broken(error.Protocol);
        if (opcode >= target.interface.events.len) return self.broken(error.Protocol);
        const event = target.interface.events[opcode];
        // Validate the body and register server-created objects before any handler sees them.
        var fd_count: usize = 0;
        var at: usize = 0;
        var nullable = false;
        for (event.signature) |code| {
            switch (code) {
                '?' => {
                    nullable = true;
                    continue;
                },
                'i', 'u', 'f', 'o' => at += 4,
                's', 'a' => {
                    if (at + 4 > body.len) return self.broken(error.Protocol);
                    at += 4 + std.mem.alignForward(usize, std.mem.readInt(u32, body[at..][0..4], .little), 4);
                },
                'n' => {
                    if (at + 4 > body.len) return self.broken(error.Protocol);
                    const created = std.mem.readInt(u32, body[at..][0..4], .little);
                    at += 4;
                    if (created == 0 and nullable) continue;
                    if (created < server_base) return self.broken(error.Protocol);
                    const interface = (event.new_id orelse return self.broken(error.Protocol))();
                    const index = created - server_base;
                    while (self.server.items.len <= index) try self.server.append(self.allocator, null);
                    self.server.items[index] = .{ .interface = interface, .version = target.version };
                },
                'h' => fd_count += 1,
                else => return self.broken(error.Protocol),
            }
            nullable = false;
        }
        if (at > body.len or fd_count > self.in_fds.items.len) return self.broken(error.Protocol);
        var fds: [max_fds]Fd = undefined;
        if (fd_count > max_fds) return self.broken(error.Protocol);
        @memcpy(fds[0..fd_count], self.in_fds.items[0..fd_count]);
        std.mem.copyForwards(Fd, self.in_fds.items[0 .. self.in_fds.items.len - fd_count], self.in_fds.items[fd_count..]);
        self.in_fds.items.len -= fd_count;
        if (self.debug) self.trace(if (target.live) "" else "discarded ", target.interface.name, id, event, body);
        var incoming: Incoming = .{ .connection = self, .id = id, .opcode = opcode, .body = body, .fds = fds[0..fd_count] };
        if (target.live) if (target.handler) |handler| handler(target.data, &incoming);
        // Descriptors the handler did not decode are closed, as libwayland does.
        for (fds[incoming.taken..fd_count]) |fd| _ = std.c.close(fd);
        if (event.destructor) self.retire(id);
    }

    /// Prints one message in libwayland's WAYLAND_DEBUG format; bodies are already validated.
    fn trace(self: *Connection, prefix: []const u8, interface: []const u8, id: u32, message: Message, body: []const u8) void {
        var line: [2048]u8 = undefined;
        var writer: std.Io.Writer = .fixed(&line);
        var clock: std.c.timespec = undefined;
        _ = std.c.clock_gettime(.REALTIME, &clock);
        const now: u64 = @intCast(@as(i64, clock.sec) * 1000 + @divTrunc(@as(i64, clock.nsec), 1_000_000));
        writer.print("[{d:>7}.{d:0>3}] {s}{s}#{d}.{s}(", .{ (now / 1000) % 10_000_000, now % 1000, prefix, interface, id, message.name }) catch {};
        var at: usize = 0;
        var first = true;
        for (message.signature) |code| {
            if (code == '?') continue;
            if (!first) writer.writeAll(", ") catch {};
            first = false;
            const word = if (code != 'h' and at + 4 <= body.len) std.mem.readInt(u32, body[at..][0..4], .little) else 0;
            switch (code) {
                'i' => writer.print("{d}", .{@as(i32, @bitCast(word))}) catch {},
                'u' => writer.print("{d}", .{word}) catch {},
                'f' => writer.print("{d:.6}", .{@as(f64, @floatFromInt(@as(i32, @bitCast(word)))) / 256}) catch {},
                's' => if (word == 0) writer.writeAll("nil") catch {} else writer.print("\"{s}\"", .{body[at + 4 ..][0 .. word - 1]}) catch {},
                'a' => writer.print("array[{d}]", .{word}) catch {},
                'o', 'n' => if (word == 0) writer.writeAll("nil") catch {} else {
                    if (code == 'n') writer.writeAll("new id ") catch {};
                    const name = if (self.object(word)) |value| value.interface.name else "[unknown]";
                    writer.print("{s}#{d}", .{ name, word }) catch {};
                },
                'h' => writer.writeAll("fd") catch {},
                else => {},
            }
            at += switch (code) {
                's', 'a' => 4 + std.mem.alignForward(usize, word, 4),
                'h' => 0,
                else => 4,
            };
        }
        writer.writeAll(")\n") catch {};
        _ = std.c.write(2, writer.buffered().ptr, writer.buffered().len);
    }

    fn displayEvent(data: ?*anyopaque, incoming: *Incoming) void {
        const self: *Connection = @ptrCast(@alignCast(data));
        switch (incoming.opcode) {
            0 => {
                const payload = incoming.decode(struct { object: Proxy, code: u32, message: [:0]const u8 }, "ous") catch return self.fail(error.Protocol);
                const name = if (self.object(payload.object.id)) |value| value.interface.name else "unknown";
                std.log.warn("wayland: {s}@{d}: error {d}: {s}", .{ name, payload.object.id, payload.code, payload.message });
                self.fail(error.Protocol);
            },
            1 => {
                const payload = incoming.decode(struct { id: u32 }, "u") catch return self.fail(error.Protocol);
                if (payload.id < server_base and payload.id > 1 and payload.id < self.client.items.len and self.client.items[payload.id] != null) {
                    self.client.items[payload.id] = null;
                    self.free.append(self.allocator, payload.id) catch {};
                }
            },
            else => {},
        }
    }

    /// Reads and dispatches without blocking, for use from a main-loop fd watch.
    pub fn readAndDispatch(self: *Connection) Error!void {
        while (try self.read()) {}
        try self.dispatchPending();
        try self.flush();
    }

    /// Flushes, then blocks until at least one message arrives and dispatches it.
    pub fn dispatch(self: *Connection) Error!void {
        try self.flush();
        try self.dispatchPending();
        while (!try self.read()) {
            var poll = [_]std.c.pollfd{.{ .fd = self.fd, .events = std.c.POLL.IN, .revents = 0 }};
            if (std.c.poll(&poll, 1, -1) < 0 and std.c._errno().* != 4) return self.broken(error.IoFailed);
        }
        try self.dispatchPending();
    }

    /// Blocks until the server has processed every request sent so far.
    pub fn roundtrip(self: *Connection) Error!void {
        var done = false;
        const callback = try self.marshal(self.display(), 0, display_interface.requests[0], &callback_interface, null, .{new_id});
        const object_ = self.object(callback.id).?;
        object_.data = &done;
        object_.handler = &struct {
            fn handle(data: ?*anyopaque, _: *Incoming) void {
                const flag: *bool = @ptrCast(@alignCast(data));
                flag.* = true;
            }
        }.handle;
        while (!done) try self.dispatch();
    }
};

fn objectId(value: anytype) u32 {
    const T = @TypeOf(value);
    if (T == Proxy) return value.id;
    if (T == @TypeOf(null)) return 0;
    return switch (@typeInfo(T)) {
        .optional => if (value) |inner| objectId(inner) else 0,
        else => value.proxy.id,
    };
}

fn put(buffer: *[max_message]u8, len: *usize, value: u32) Error!void {
    if (len.* + 4 > buffer.len) return error.Protocol;
    std.mem.writeInt(u32, buffer[len.*..][0..4], value, .little);
    len.* += 4;
}

fn putArray(buffer: *[max_message]u8, len: *usize, value: []const u8) Error!void {
    const padded = std.mem.alignForward(usize, value.len, 4);
    if (len.* + 4 + padded > buffer.len) return error.Protocol;
    try put(buffer, len, @intCast(value.len));
    @memset(buffer[len.*..][0..padded], 0);
    @memcpy(buffer[len.*..][0..value.len], value);
    len.* += padded;
}

fn putString(buffer: *[max_message]u8, len: *usize, value: anytype) Error!void {
    const T = @TypeOf(value);
    const text: ?[]const u8 = switch (@typeInfo(T)) {
        .optional => if (value) |inner| inner else null,
        .null => null,
        else => value,
    };
    const bytes = text orelse return put(buffer, len, 0);
    const padded = std.mem.alignForward(usize, bytes.len + 1, 4);
    if (len.* + 4 + padded > buffer.len) return error.Protocol;
    try put(buffer, len, @intCast(bytes.len + 1));
    @memset(buffer[len.*..][0..padded], 0);
    @memcpy(buffer[len.*..][0..bytes.len], bytes);
    len.* += padded;
}

fn cmsgSpace(count: usize) usize {
    return 16 + std.mem.alignForward(usize, count * 4, 8);
}

fn writeCmsg(control: []u8, fds: []const Fd) void {
    std.mem.writeInt(usize, control[0..8], 16 + fds.len * 4, .little);
    std.mem.writeInt(i32, control[8..12], 1, .little); // SOL_SOCKET
    std.mem.writeInt(i32, control[12..16], 1, .little); // SCM_RIGHTS
    for (fds, 0..) |fd, i| std.mem.writeInt(i32, control[16 + i * 4 ..][0..4], fd, .little);
}

const SockaddrUn = extern struct {
    family: u16 = 1,
    path: [108]u8 = @splat(0),
};

extern "c" fn unsetenv(name: [*:0]const u8) c_int;
extern "c" fn socketpair(domain: c_int, kind: c_int, protocol: c_int, fds: *[2]Fd) c_int;

// ---------------------------------------------------------------- Tests

const test_registry: Interface = .{ .name = "wl_registry", .version = 1, .requests = &.{
    .{ .name = "bind", .signature = "usun" },
}, .events = &.{
    .{ .name = "global", .signature = "usu" },
    .{ .name = "global_remove", .signature = "u" },
} };
const test_thing: Interface = .{ .name = "test_thing", .version = 3, .requests = &.{
    .{ .name = "set", .signature = "if?s?oah" },
    .{ .name = "destroy", .signature = "", .destructor = true },
}, .events = &.{
    .{ .name = "info", .signature = "if?sah" },
    .{ .name = "child", .signature = "n", .new_id = struct {
        fn get() *const Interface {
            return &test_thing;
        }
    }.get },
} };
const Registry = struct {
    proxy: Proxy,
    pub const interface = test_registry;
    pub const Event = union(enum) {
        global: struct { name: u32, interface: [:0]const u8, version: u32 },
        global_remove: struct { name: u32 },
    };
};
const Thing = struct {
    proxy: Proxy,
    pub const interface = test_thing;
    pub const Event = union(enum) {
        info: struct { number: i32, scale: f64, label: ?[:0]const u8, blob: []const u8, fd: Fd },
        child: struct { id: Thing },
    };
};

fn pair() ![2]Fd {
    var fds: [2]Fd = undefined;
    if (socketpair(1, 1 | 0o2000000, 0, &fds) != 0) return error.IoFailed;
    return fds;
}

fn readAll(fd: Fd, buffer: []u8) !usize {
    const n = std.c.read(fd, buffer.ptr, buffer.len);
    if (n < 0) return error.IoFailed;
    return @intCast(n);
}

test "requests encode ids, strings, arrays, fixed values and descriptors" {
    const fds = try pair();
    defer _ = std.c.close(fds[1]);
    const connection = try Connection.fromFd(std.testing.allocator, fds[0]);
    defer connection.deinit();
    const registry = connection.display().send(1, display_interface.requests[1], &test_registry, null, .{new_id});
    try std.testing.expectEqual(@as(u32, 2), registry.id);
    const thing = registry.send(0, test_registry.requests[0], &test_thing, 3, .{ 7, "test_thing", 3, new_id });
    try std.testing.expectEqual(@as(u32, 3), thing.id);
    try std.testing.expectEqual(@as(u32, 3), thing.version());
    _ = thing.send(0, test_thing.requests[0], null, null, .{ -5, 1.5, "hi", registry, "abcde", fds[1] });
    try connection.flush();
    var buffer: [256]u8 align(4) = undefined;
    const len = try readAll(fds[1], &buffer);
    const words = std.mem.bytesAsSlice(u32, buffer[0..len]);
    // get_registry: id 1, opcode 1, size 12, new id 2.
    try std.testing.expectEqualSlices(u32, &.{ 1, 12 << 16 | 1, 2 }, words[0..3]);
    // bind: name 7, "test_thing\0" padded to 12, version 3, new id 3.
    try std.testing.expectEqualSlices(u32, &.{ 2, 36 << 16, 7, 11 }, words[3..7]);
    try std.testing.expectEqualStrings("test_thing", buffer[28..38]);
    try std.testing.expectEqualSlices(u32, &.{ 3, 3 }, words[10..12]);
    // set: -5, 1.5 as 384, "hi", object 2, 5-byte array; the fd travels out of band.
    try std.testing.expectEqualSlices(u32, &.{ 3, 40 << 16, @bitCast(@as(i32, -5)), 384, 3 }, words[12..17]);
    try std.testing.expectEqualSlices(u32, &.{ 2, 5 }, words[18..20]);
    try std.testing.expectEqualStrings("abcde", buffer[80..85]);
    _ = thing.send(1, test_thing.requests[1], null, null, .{});
    try std.testing.expect(!connection.object(3).?.live);
}

test "events decode into typed payloads with descriptors and server objects" {
    const fds = try pair();
    defer _ = std.c.close(fds[1]);
    const connection = try Connection.fromFd(std.testing.allocator, fds[0]);
    defer connection.deinit();
    const registry: Registry = .{ .proxy = connection.display().send(1, display_interface.requests[1], &test_registry, null, .{new_id}) };
    const thing: Thing = .{ .proxy = registry.proxy.send(0, test_registry.requests[0], &test_thing, 2, .{ 1, "test_thing", 2, new_id }) };
    const Seen = struct {
        globals: u32 = 0,
        name: [32]u8 = undefined,
        number: i32 = 0,
        scale: f64 = 0,
        label: bool = true,
        blob: [8]u8 = undefined,
        fd: Fd = -1,
        child: ?Thing = null,
        fn onRegistry(self: *@This(), _: Registry, event: Registry.Event) void {
            switch (event) {
                .global => |global| {
                    self.globals += global.name * global.version;
                    @memcpy(self.name[0..global.interface.len], global.interface);
                },
                .global_remove => |removed| self.globals += removed.name * 100,
            }
        }
        fn onThing(self: *@This(), _: Thing, event: Thing.Event) void {
            switch (event) {
                .info => |info| {
                    self.number = info.number;
                    self.scale = info.scale;
                    self.label = info.label != null;
                    @memcpy(self.blob[0..info.blob.len], info.blob);
                    self.fd = info.fd;
                },
                .child => |child| self.child = child.id,
            }
        }
    };
    var seen: Seen = .{};
    registry.proxy.listen(Registry, Seen, &seen, Seen.onRegistry);
    thing.proxy.listen(Thing, Seen, &seen, Seen.onThing);
    const messages = [_]u32{
        // global(9, "wl_seat", 4), then global_remove(4).
        2, 28 << 16 | 0, 9, 8, std.mem.readInt(u32, "wl_s", .little), std.mem.readInt(u32, "eat\x00", .little), 4,
        2, 12 << 16 | 1, 4,
        // info(-2, 2.25, null, "xyz", fd), then child(0xff000000).
        3, 28 << 16 | 0, @bitCast(@as(i32, -2)), 576, 0, 3, std.mem.readInt(u32, "xyz\x00", .little),
        3, 12 << 16 | 1, 0xff000000,
        // delete_id(3) releases the client id for reuse.
        1, 12 << 16 | 1, 3,
    };
    const bytes = std.mem.asBytes(&messages);
    var control: [cmsgSpace(1)]u8 align(8) = @splat(0);
    const passed = std.c.dup(0);
    defer _ = std.c.close(passed);
    writeCmsg(&control, &.{passed});
    var iov = [_]std.posix.iovec_const{.{ .base = bytes, .len = bytes.len }};
    const header: std.c.msghdr_const = .{ .name = null, .namelen = 0, .iov = &iov, .iovlen = 1, .control = &control, .controllen = control.len, .flags = 0 };
    try std.testing.expect(std.c.sendmsg(fds[1], &header, 0) == bytes.len);
    try connection.readAndDispatch();
    try std.testing.expectEqual(@as(u32, 9 * 4 + 400), seen.globals);
    try std.testing.expectEqualStrings("wl_seat", seen.name[0..7]);
    try std.testing.expectEqual(@as(i32, -2), seen.number);
    try std.testing.expectEqual(@as(f64, 2.25), seen.scale);
    try std.testing.expect(!seen.label);
    try std.testing.expectEqualStrings("xyz", seen.blob[0..3]);
    try std.testing.expect(seen.fd >= 0);
    _ = std.c.close(seen.fd);
    try std.testing.expectEqual(@as(u32, 0xff000000), seen.child.?.proxy.id);
    try std.testing.expectEqual(@as(u32, 2), seen.child.?.proxy.version());
    try std.testing.expect(connection.object(3) == null);
    // The next client object reuses id 3.
    const again = registry.proxy.send(0, test_registry.requests[0], &test_thing, 1, .{ 1, "test_thing", 1, new_id });
    try std.testing.expectEqual(@as(u32, 3), again.id);
}

test "protocol errors from the server stop the connection" {
    const fds = try pair();
    defer _ = std.c.close(fds[1]);
    const connection = try Connection.fromFd(std.testing.allocator, fds[0]);
    defer connection.deinit();
    const message = [_]u32{ 1, 28 << 16 | 0, 1, 3, 8, std.mem.readInt(u32, "bad ", .little), std.mem.readInt(u32, "id!\x00", .little) };
    const bytes = std.mem.sliceAsBytes(&message);
    try std.testing.expect(std.c.write(fds[1], bytes.ptr, bytes.len) == bytes.len);
    try std.testing.expectError(error.Protocol, connection.readAndDispatch());
    try std.testing.expectError(error.Protocol, connection.flush());
}

test "a closed socket is reported" {
    const fds = try pair();
    const connection = try Connection.fromFd(std.testing.allocator, fds[0]);
    defer connection.deinit();
    _ = std.c.close(fds[1]);
    try std.testing.expectError(error.ConnectionClosed, connection.readAndDispatch());
}
